    rows: [
    { id: "a-details", kind: "criterion", verbatim: "Any 8 x 5 marks", marks: 40, contextNote: "Credit the best EIGHT acceptable details at 5 marks each, capped at 40. Marked details: concrete block outer leaf with external render; full-fill insulated cavity with wall tie; concrete block inner leaf with internal plaster; wallplate with cavity closer; waterproof membrane; insulation; plywood decking with breather membrane; firring piece; insulated ceiling joist; insulated plasterboard ceiling with airtight membrane; fascia and soffit; gutter. The model specifies 19 mm render, 100 mm leaves, a 200 mm cavity, 15 mm plaster, a 100 × 75 mm wallplate, 150 mm insulation, 20 mm plywood, 200 × 50 mm joists and a 50 mm insulated plasterboard ceiling.", permittedMarks: [0,5,10,15,20,25,30,35,40] },
    { id: "a-presentation", kind: "criterion", verbatim: "Draughting, accuracy and scale (excellent, good, fair)", marks: 6, contextNote: "Draughting, accuracy and scale of the section: excellent 6, good 4, fair 2.", permittedMarks: [0,2,4,6] },
    { id: "b-closer", kind: "criterion", verbatim: "Cavity closer", marks: 4, contextNote: "Show and identify the cavity closer at wallplate level, as in the scheme’s model detail. Any other suitable detail is accepted.", permittedMarks: [0,4] },
    ],
